 public static function form(Schema $schema): Schema {return $schema->columns(2)->components([Select::make('event_project_id')->label('Édition')->relationship('eventProject','name')->required()->disabledOn('edit'),TextInput::make('source_key')->label('Référence unique du site')->required(),TextInput::make('entity_key')->label('Groupe entreprise · éviter les doublons de contact')->required(),TextInput::make('name')->label('Établissement')->required(),TextInput::make('category')->label('Catégorie')->required(),TextInput::make('municipality')->label('Município')->required(),TextInput::make('contact_name')->label('Interlocuteur professionnel'),Textarea::make('contact_source')->label('Origine des coordonnées et motif de suivi'),DateTimePicker::make('followup_at')->label('Prochaine relance')->timezone('Europe/Lisbon'),TextInput::make('sector')->label('Secteur géographique')->required(),TextInput::make('tour')->label('Tournée')->required(),TextInput::make('priority')->label('Priorité 1 à 3')->integer()->minValue(1)->maxValue(3)->default(2)->required(),TextInput::make('visit_order')->label('Ordre de visite dans la tournée')->integer()->minValue(0)->default(100)->required(),Textarea::make('address')->label('Adresse · confirmer avant départ')->required(),TextInput::make('phone')->label('Téléphone professionnel'),TextInput::make('email')->label('Email professionnel')->email(),Toggle::make('address_confirmed')->label('Adresse confirmée par contact'),DateTimePicker::make('appointment_at')->label('Rendez-vous convenu')->timezone('Europe/Lisbon'),Select::make('status')->label('Suivi')->options(['new'=>'À qualifier','to_call'=>'À appeler avant trajet','appointment'=>'Rendez-vous fixé','contacted'=>'Contact établi','qualified'=>'Intérêt qualifié','declined'=>'Décliné'])->default('new')->required(),Textarea::make('opportunity')->label('Proposition adaptée')->columnSpanFull(),Textarea::make('next_action')->label('Prochaine action')->columnSpanFull(),Textarea::make('source')->label('So